const ProductVideoVerdict: React.FC<{ productId: number; isWinner?: boolean }> = ({ productId, isWinner }) => {
  const [isPlaying, setIsPlaying] = useState(false);
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const video = productVideos[productId];
  if (!video) return null;

  const playVideo = () => {
    videoRef.current?.play().catch(() => setIsPlaying(false));
  };

  return (
    <div className={`mb-8 overflow-hidden rounded-3xl border shadow-sm ${
      isWinner ? 'border-emerald-200 bg-emerald-50/50' : 'border-slate-200 bg-slate-50'
    }`}>
      <div className="grid grid-cols-1 md:grid-cols-[220px_1fr] lg:grid-cols-[260px_1fr]">
        <div className="relative bg-black">
          <video
            ref={videoRef}
            className="no-fullscreen-video block w-full aspect-[9/16] object-cover"
            controls
            controlsList="nodownload nofullscreen noremoteplayback"
            disablePictureInPicture
            playsInline
            preload="metadata"
            poster={video.poster}
            onPlay={() => setIsPlaying(true)}
            onPause={() => setIsPlaying(false)}
            onEnded={() => setIsPlaying(false)}
          >
            <source src={video.src} type={video.src.endsWith('.mp4') ? 'video/mp4' : 'video/webm'} />
            Your browser does not support the video tag.
          </video>
          <button
            type="button"
            aria-label={`Play ${video.headline} video`}
            onClick={playVideo}
            className={`absolute left-1/2 top-1/2 z-20 flex h-16 w-16 -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-full bg-white/95 text-emerald-700 shadow-[0_18px_40px_rgba(0,0,0,0.28)] ring-8 ring-white/35 transition-all duration-300 hover:scale-105 focus:outline-none focus:ring-emerald-200 ${
              isPlaying ? 'pointer-events-none opacity-0 scale-90' : 'opacity-100 scale-100'
            }`}
          >
            <Play size={30} fill="currentColor" className="ml-1" />
          </button>
        </div>
        <div className="flex flex-col justify-center p-6 md:p-8">
          <p className={`mb-3 text-xs font-black uppercase tracking-[0.22em] ${isWinner ? 'text-emerald-700' : 'text-slate-500'}`}>
            {video.label}
          </p>
          <h3 className="mb-4 font-serif text-2xl font-bold leading-tight text-slate-950 md:text-3xl">
            {video.headline}
          </h3>
          <p className="text-base leading-relaxed text-slate-600 md:text-lg">
            {video.copy}
          </p>
        </div>
      </div>
    </div>
  );
};

